--[[ LLOYD v7 PROTECTED | multi-part lattice | smooth runtime ]]
if _G.__LloydV7Boot then return end; _G.__LloydV7Boot = true

local char, byte, concat, gsub = string.char, string.byte, table.concat, string.gsub
local bxor, band
if bit32 then bxor, band = bit32.bxor, bit32.band
elseif bit then bxor, band = bit.bxor, bit.band
else
  band = function(a,b) local r,p=0,1; a,b=a%256,b%256; for i=1,8 do if a%2==1 and b%2==1 then r=r+p end; a,b,p=math.floor(a/2),math.floor(b/2),p*2 end; return r end
  bxor = function(a,b) local r,p=0,1; a,b=a%256,b%256; for i=1,8 do if a%2~=b%2 then r=r+p end; a,b,p=math.floor(a/2),math.floor(b/2),p*2 end; return r end
end

local function b64decode(data)
  local alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
  data=gsub(data,'[^'..alphabet..'=]','')
  local t={} local n=0
  local function push(c) n=n+1; t[n]=char(c) end
  local buf, bits = 0, 0
  for i=1,#data do
    local c=data:sub(i,i)
    if c~='=' then
      local v=(alphabet:find(c,1,true) or 1)-1
      buf = buf*64 + v; bits = bits + 6
      if bits >= 8 then
        bits = bits - 8
        push(math.floor(buf / (2^bits)) % 256)
        buf = buf % (2^bits)
      end
    end
  end
  return concat(t)
end

