local function decode()
  local pieces=table.create and table.create(#SEGS) or {}
  for i=1,#SEGS do pieces[i]=SEGS[i] end
  local enc=concat(pieces)
  local raw=b64decode(enc)
  local n=#raw
  local out=table.create and table.create(n) or {}
  -- fast path: process in blocks
  for i=1,n do
    local m = ((i-1)*73+19)%256
    out[i]=char(bxor(bxor(byte(raw,i), K[((i-1)%32)+1]), m))
  end
  return concat(out)
end

local function boot()
  local src = decode()
  -- wipe ciphertext from memory as much as possible
  for i=1,#SEGS do SEGS[i]=nil end
  SEGS=nil
  local loader = loadstring or load
  local fn, err = loader(src)
  src=nil
  if not fn then
    warn('[Lloyd Protected] compile error:', err)
    return
  end
  local ok, e = pcall(fn)
  if not ok then warn('[Lloyd Protected] runtime:', e) end
end

task.spawn(boot)